import assert from 'node:assert/strict';
import { test } from 'node:test';
import { mergeConfig } from '../src/config.js';

test('merges at multiple depths while retaining unrelated keys on both sides', () => {
  const defaults = { server: { host: 'localhost', port: 8080, tls: { enabled: true, cert: { path: 'old', format: 'pem' } } }, level: 'info' };
  const overrides = { server: { port: 9090, tls: { cert: { path: 'new' }, mode: 'strict' } }, file: 'app.log' };
  assert.deepEqual(mergeConfig(defaults, overrides), { server: { host: 'localhost', port: 9090, tls: { enabled: true, cert: { path: 'new', format: 'pem' }, mode: 'strict' } }, level: 'info', file: 'app.log' });
});

test('empty nested overrides retain defaults and multiple sibling branches merge independently', () => {
  assert.deepEqual(mergeConfig({ a: { x: 1 }, b: { inner: { x: 2, y: 3 } }, c: { z: 4 } }, { a: {}, b: { inner: { y: 9 } }, c: { q: 5 } }), { a: { x: 1 }, b: { inner: { x: 2, y: 9 } }, c: { z: 4, q: 5 } });
});

test('recursive merging does not write into either argument', () => {
  const defaults = Object.freeze({ a: Object.freeze({ b: Object.freeze({ keep: 1, change: 2 }) }) });
  const overrides = Object.freeze({ a: Object.freeze({ b: Object.freeze({ change: 3 }) }) });
  assert.deepEqual(mergeConfig(defaults, overrides), { a: { b: { keep: 1, change: 3 } } });
  assert.deepEqual(defaults, { a: { b: { keep: 1, change: 2 } } });
  assert.deepEqual(overrides, { a: { b: { change: 3 } } });
});

test('null-prototype records also merge key by key', () => {
  const a = Object.assign(Object.create(null), { keep: 1, change: 2 });
  const b = Object.assign(Object.create(null), { change: 3 });
  const result = mergeConfig({ nested: a }, { nested: b });
  assert.equal(result.nested.keep, 1);
  assert.equal(result.nested.change, 3);
  assert.deepEqual(Object.keys(result.nested).sort(), ['change', 'keep']);
});

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { mergeConfig } from '../src/config.js';

test('non-plain overrides replace whole values at the top level and inside records', () => {
  class Setting { constructor() { this.selected = true; } }
  for (const value of [['c'], [], null, 'custom', '', 0, 42, false, undefined, new Date(0), new Setting()]) {
    const defaults = { value: { keep: 1, selected: false } };
    const overrides = { value };
    assert.deepEqual(mergeConfig(defaults, overrides), { value });
    assert.deepEqual(defaults, { value: { keep: 1, selected: false } });
    assert.deepEqual(overrides, { value });
    const nested = mergeConfig({ outer: { value: { keep: 1 } } }, { outer: { value } });
    assert.deepEqual(nested, { outer: { value } });
  }
  assert.deepEqual(mergeConfig({ tags: ['a', 'b'] }, { tags: ['c'] }), { tags: ['c'] });
});

test('plain objects replace non-plain defaults without retaining their properties', () => {
  class Setting { constructor() { this.old = 1; } }
  for (const value of [null, undefined, 7, 'abc', [1, 2], new Date(0), new Setting()]) {
    assert.deepEqual(mergeConfig({ key: value }, { key: { fresh: 2 } }), { key: { fresh: 2 } });
  }
});

test('flat merging, empty arguments, own keys and undefined overrides retain existing semantics', () => {
  assert.deepEqual(mergeConfig({ level: 'info', color: true }, { level: 'debug', file: 'app.log' }), { level: 'debug', color: true, file: 'app.log' });
  assert.deepEqual(mergeConfig({}, {}), {});
  assert.deepEqual(mergeConfig({ a: 1 }, {}), { a: 1 });
  assert.deepEqual(mergeConfig({}, { a: 1 }), { a: 1 });
  assert.deepEqual(mergeConfig({ a: 1 }, { a: undefined }), { a: undefined });
  const inherited = Object.create({ hidden: 1 });
  inherited.visible = 2;
  assert.deepEqual(mergeConfig({ a: 1 }, inherited), { a: 1, visible: 2 });
  const key = Symbol('key');
  assert.deepEqual(mergeConfig({ [key]: 1, a: 2 }, { [key]: 3 }), { [key]: 3, a: 2 });
});

test('inputs remain unchanged for replacements and omitted branches', () => {
  const defaults = Object.freeze({ tags: Object.freeze(['a', 'b']), untouched: Object.freeze({ x: 1 }), count: 1 });
  const overrides = Object.freeze({ tags: Object.freeze(['c']), count: 2 });
  assert.deepEqual(mergeConfig(defaults, overrides), { tags: ['c'], untouched: { x: 1 }, count: 2 });
  assert.deepEqual(defaults, { tags: ['a', 'b'], untouched: { x: 1 }, count: 1 });
  assert.deepEqual(overrides, { tags: ['c'], count: 2 });
});
